#[test]
fn connected_tailscale_without_private_dns_origin_is_distinct() {
    let cli = FakeCli::new(vec![FakeCli::ok(
        &serde_json::json!({"BackendState": "Running", "Self": {}}).to_string(),
    )]);
    assert!(matches!(
        reconcile_tailscale(&cli, "http://127.0.0.1:59368", None),
        Err(TailscalePublicationError::OriginUnavailable)
    ));
    assert_eq!(cli.calls().len(), 1);
}

#[test]
fn serve_administrator_failure_is_actionable_and_does_not_retry() {
    let cli = FakeCli::new(vec![
        running_status(),
        FakeCli::ok("{}"),
        FakeCli::ok("{}"),
        Ok(CliOutput {
            success: false,
            stdout: String::new(),
            stderr: "Access is denied; administrator approval required".to_owned(),
        }),
    ]);
    assert!(matches!(
        reconcile_tailscale(&cli, "http://127.0.0.1:59368", None),
        Err(TailscalePublicationError::AdministratorRequired)
    ));
    assert_eq!(cli.calls().len(), 4);
}

